package com.bank.oltp.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class TransferService {
    private static final Logger log = LoggerFactory.getLogger(TransferService.class);
    private final JdbcTemplate oltp;

    public TransferService(JdbcTemplate oltp) { this.oltp = oltp; }

    // OLTP: tiny, fast, single-row updates on the PostgreSQL primary.
    @Transactional
    public void transfer(String fromId, String toId, BigDecimal amount) {
        oltp.update("UPDATE accounts SET balance = balance - ? WHERE account_id = ?", amount, fromId);
        oltp.update("UPDATE accounts SET balance = balance + ? WHERE account_id = ?", amount, toId);
        log.info("OLTP transfer {} from {} to {}", amount, fromId, toId);
    }
}
