package com.bank.analytics.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

@Service
public class AnalyticsService {
    private static final Logger log = LoggerFactory.getLogger(AnalyticsService.class);
    private final JdbcTemplate olap;   // points at the columnar warehouse, NOT the primary

    public AnalyticsService(JdbcTemplate olap) { this.olap = olap; }

    // OLAP: heavy aggregation scanning few columns over billions of rows.
    // Runs on Redshift/BigQuery so it never touches the live OLTP database.
    public List<Map<String, Object>> monthlyDepositTotals() {
        log.info("Running 5-year deposit aggregation on the OLAP warehouse");
        return olap.queryForList(
            "SELECT date_trunc('month', txn_date) AS month, SUM(amount) AS total " +
            "FROM fact_transactions WHERE txn_type='DEPOSIT' " +
            "GROUP BY 1 ORDER BY 1");
    }
}
